/**
 * Arc Wallet SDK - Main Class
 * Provides a simple API for integrating passkey-based wallets
 */

import { JsonRpcProvider } from 'ethers';
import { WebAuthnManager } from '../core/webauthn';
import { SecureStorage } from '../core/secureStorage';
import { KeyManager } from '../core/keyManager';
import { CCTPManager } from '../core/cctpManager';
import { SmartAccountManager } from '../core/smartAccountManager';
import type {
  WalletSDKConfig,
  WalletAccount,
  TransactionRequest,
  SignedTransaction,
  WalletEvent,
  WalletEventPayload,
} from '../types';
import type { CCTPTransferParams, CCTPTransferResult } from '../types/cctp';
import type {
  UserOperationRequest,
  UserOperationResult,
  BatchTransaction,
} from '../types/account-abstraction';
import { logger } from '../utils/logger';

export class WalletSDK {
  private webauthn: WebAuthnManager;
  private storage: SecureStorage;
  private keyManager: KeyManager;
  private cctpManager: CCTPManager;
  private smartAccountManager: SmartAccountManager | null = null;
  private provider: JsonRpcProvider;
  private eventListeners: Map<WalletEvent, Set<(payload: any) => void>>;
  private currentAccount: WalletAccount | null = null;
  private accountType: 'eoa' | 'smart-account';

  constructor(config: WalletSDKConfig) {

    // Initialize core components
    this.webauthn = new WebAuthnManager({
      rpId: config.rpId,
      rpName: config.appName,
      backendUrl: config.backendUrl,
    });

    this.storage = new SecureStorage();
    this.keyManager = new KeyManager(this.webauthn, this.storage);
    this.provider = new JsonRpcProvider(config.rpcUrl);
    this.cctpManager = new CCTPManager(this.provider, config.cctp);
    this.accountType = config.accountType || 'eoa';

    // Initialize Smart Account Manager if enabled
    if (this.accountType === 'smart-account') {
      this.smartAccountManager = new SmartAccountManager(
        this.provider,
        config.smartAccount,
        config.paymaster
      );
    }

    this.eventListeners = new Map();

    logger.debug('Initialized with config', {
      appName: config.appName,
      rpId: config.rpId,
      rpcUrl: config.rpcUrl,
      accountType: this.accountType,
    });
  }

  /**
   * Create new wallet with passkey
   */
  async createWallet(userId: string, userName: string): Promise<WalletAccount> {
    try {
      logger.info('Creating new wallet', { component: 'WalletSDK', action: 'createWallet' });

      const account = await this.keyManager.createWallet(userId, userName);
      this.currentAccount = account;

      this.emit('connect', { address: account.address });

      logger.info('Wallet created', { component: 'WalletSDK', address: account.address });

      return account;
    } catch (error: any) {
      this.emit('error', {
        message: error.message,
        code: 'CREATE_WALLET_FAILED',
      });
      throw error;
    }
  }

  /**
   * Connect to existing wallet (unlock with passkey)
   */
  async connect(credentialId?: string): Promise<WalletAccount> {
    try {
      logger.info('Connecting wallet', { component: 'WalletSDK', action: 'connect' });

      const account = await this.keyManager.unlockWallet(credentialId);
      this.currentAccount = account;

      this.emit('connect', { address: account.address });

      logger.info('Connected', { component: 'WalletSDK', address: account.address });

      return account;
    } catch (error: any) {
      this.emit('error', {
        message: error.message,
        code: 'CONNECT_FAILED',
      });
      throw error;
    }
  }

  /**
   * Disconnect wallet (lock)
   */
  disconnect(): void {
    this.keyManager.lock();
    this.currentAccount = null;

    this.emit('disconnect', { reason: 'User disconnected' });

    logger.info('Disconnected', { component: 'WalletSDK' });
  }

  /**
   * Sign and send transaction
   */
  async signTransaction(txRequest: TransactionRequest): Promise<SignedTransaction> {
    if (!this.currentAccount) {
      throw new Error('No wallet connected. Please connect first.');
    }

    try {
      logger.info('Signing transaction', { component: 'WalletSDK' });

      // Prepare transaction
      const tx = {
        to: txRequest.to,
        value: txRequest.value,
        data: txRequest.data || '0x',
        gasLimit: txRequest.gasLimit,
        maxFeePerGas: txRequest.maxFeePerGas,
        maxPriorityFeePerGas: txRequest.maxPriorityFeePerGas,
      };

      // Fill in gas parameters if not provided
      if (!tx.gasLimit) {
        const estimated = await this.provider.estimateGas({
          to: tx.to,
          value: tx.value,
          data: tx.data,
        });
        tx.gasLimit = estimated;
      }

      if (!tx.maxFeePerGas || !tx.maxPriorityFeePerGas) {
        const feeData = await this.provider.getFeeData();
        tx.maxFeePerGas = tx.maxFeePerGas || feeData.maxFeePerGas || undefined;
        tx.maxPriorityFeePerGas =
          tx.maxPriorityFeePerGas || feeData.maxPriorityFeePerGas || undefined;
      }

      // Sign transaction
      const signedTx = await this.keyManager.signTransaction(tx);

      // Send transaction
      const response = await this.provider.broadcastTransaction(signedTx);
      const receipt = await response.wait();

      const result: SignedTransaction = {
        hash: receipt!.hash,
        signedTx,
        from: this.currentAccount.address,
        to: txRequest.to,
        value: txRequest.value,
      };

      this.emit('transactionSigned', { hash: receipt!.hash });

      logger.info('Transaction sent', { component: 'WalletSDK', hash: receipt!.hash });

      return result;
    } catch (error: any) {
      this.emit('error', {
        message: error.message,
        code: 'TRANSACTION_FAILED',
      });
      throw error;
    }
  }

  /**
   * Sign message
   */
  async signMessage(message: string): Promise<string> {
    if (!this.currentAccount) {
      throw new Error('No wallet connected. Please connect first.');
    }

    try {
      logger.info('Signing message', { component: 'WalletSDK' });
      const signature = await this.keyManager.signMessage(message);
      logger.info('Message signed', { component: 'WalletSDK' });
      return signature;
    } catch (error: any) {
      this.emit('error', {
        message: error.message,
        code: 'SIGN_MESSAGE_FAILED',
      });
      throw error;
    }
  }

  /**
   * Get current account
   */
  getAccount(): WalletAccount | null {
    return this.currentAccount;
  }

  /**
   * Get current address
   */
  getAddress(): string | null {
    return this.currentAccount?.address || null;
  }

  /**
   * Check if wallet is connected
   */
  isConnected(): boolean {
    return this.currentAccount !== null;
  }

  /**
   * Get provider for advanced usage
   */
  getProvider(): JsonRpcProvider {
    return this.provider;
  }

  /**
   * Subscribe to events
   */
  on<E extends WalletEvent>(
    event: E,
    listener: (payload: WalletEventPayload[E]) => void
  ): void {
    if (!this.eventListeners.has(event)) {
      this.eventListeners.set(event, new Set());
    }
    this.eventListeners.get(event)!.add(listener);
  }

  /**
   * Unsubscribe from events
   */
  off<E extends WalletEvent>(
    event: E,
    listener: (payload: WalletEventPayload[E]) => void
  ): void {
    const listeners = this.eventListeners.get(event);
    if (listeners) {
      listeners.delete(listener);
    }
  }

  /**
   * Emit event
   */
  private emit<E extends WalletEvent>(event: E, payload: WalletEventPayload[E]): void {
    const listeners = this.eventListeners.get(event);
    if (listeners) {
      listeners.forEach((listener) => listener(payload));
    }
  }

  /**
   * Transfer USDC cross-chain using CCTP
   */
  async transferUSDC(params: CCTPTransferParams): Promise<CCTPTransferResult> {
    if (!this.currentAccount) {
      throw new Error('No wallet connected. Please connect first.');
    }

    if (!this.keyManager['currentWallet']) {
      throw new Error('Wallet not unlocked. Please authenticate first.');
    }

    try {
      logger.info('Initiating CCTP transfer', { component: 'WalletSDK' });

      const wallet = this.keyManager['currentWallet'];
      const result = await this.cctpManager.transferUSDC(wallet, params);

      this.emit('transactionSigned', { hash: result.sourceTxHash });

      logger.info('CCTP transfer initiated', { component: 'WalletSDK', sourceTxHash: result.sourceTxHash });

      return result;
    } catch (error: any) {
      this.emit('error', {
        message: error.message,
        code: 'CCTP_TRANSFER_FAILED',
      });
      throw error;
    }
  }

  /**
   * Get USDC balance
   */
  async getUSDCBalance(chainId?: number): Promise<string> {
    if (!this.currentAccount) {
      throw new Error('No wallet connected');
    }

    return await this.cctpManager.getUSDCBalance(this.currentAccount.address, chainId);
  }

  /**
   * Send UserOperation (Smart Account only)
   */
  async sendUserOperation(request: UserOperationRequest): Promise<UserOperationResult> {
    if (this.accountType !== 'smart-account' || !this.smartAccountManager) {
      throw new Error('Smart Account mode not enabled. Set accountType to "smart-account"');
    }

    if (!this.currentAccount) {
      throw new Error('No wallet connected. Please connect first.');
    }

    if (!this.keyManager['currentWallet']) {
      throw new Error('Wallet not unlocked. Please authenticate first.');
    }

    try {
      logger.debug('Building UserOperation', { component: 'WalletSDK' });

      const wallet = this.keyManager['currentWallet'];
      const userOp = await this.smartAccountManager.buildUserOperation(wallet, request);

      logger.info('Sending UserOperation', { component: 'WalletSDK' });
      const result = await this.smartAccountManager.sendUserOperation(userOp);

      this.emit('transactionSigned', { hash: result.userOpHash });

      logger.info('UserOperation sent', { component: 'WalletSDK', userOpHash: result.userOpHash });

      return result;
    } catch (error: any) {
      this.emit('error', {
        message: error.message,
        code: 'USER_OPERATION_FAILED',
      });
      throw error;
    }
  }

  /**
   * Batch transactions (Smart Account only)
   */
  async batchTransactions(
    transactions: BatchTransaction[],
    sponsored = false
  ): Promise<UserOperationResult> {
    if (this.accountType !== 'smart-account' || !this.smartAccountManager) {
      throw new Error('Smart Account mode not enabled. Set accountType to "smart-account"');
    }

    if (!this.currentAccount) {
      throw new Error('No wallet connected. Please connect first.');
    }

    if (!this.keyManager['currentWallet']) {
      throw new Error('Wallet not unlocked. Please authenticate first.');
    }

    try {
      logger.debug('Building batch UserOperation', { component: 'WalletSDK' });

      const wallet = this.keyManager['currentWallet'];
      const userOp = await this.smartAccountManager.buildBatchUserOperation(
        wallet,
        transactions,
        sponsored
      );

      logger.info('Sending batch UserOperation', { component: 'WalletSDK' });
      const result = await this.smartAccountManager.sendUserOperation(userOp);

      this.emit('transactionSigned', { hash: result.userOpHash });

      logger.info('Batch UserOperation sent', { component: 'WalletSDK', userOpHash: result.userOpHash });

      return result;
    } catch (error: any) {
      this.emit('error', {
        message: error.message,
        code: 'BATCH_TRANSACTION_FAILED',
      });
      throw error;
    }
  }

  /**
   * Get Smart Account address (counterfactual)
   */
  getSmartAccountAddress(): string | null {
    if (this.accountType !== 'smart-account' || !this.smartAccountManager) {
      return null;
    }

    if (!this.currentAccount) {
      return null;
    }

    return this.smartAccountManager.getAccountAddress(this.currentAccount.address);
  }

  /**
   * Check if Smart Account is deployed
   */
  async isSmartAccountDeployed(): Promise<boolean> {
    if (this.accountType !== 'smart-account' || !this.smartAccountManager) {
      return false;
    }

    const smartAccountAddress = this.getSmartAccountAddress();
    if (!smartAccountAddress) {
      return false;
    }

    return await this.smartAccountManager.isDeployed(smartAccountAddress);
  }

  /**
   * Delete wallet permanently
   */
  async deleteWallet(): Promise<void> {
    if (!this.currentAccount) {
      throw new Error('No wallet connected');
    }

    const credentialId = this.currentAccount.credentialId;
    await this.keyManager.deleteWallet(credentialId);

    this.disconnect();

    logger.info('Wallet deleted permanently', { component: 'WalletSDK' });
  }
}
